import{_ as a,C as r,o as s,c as l,j as t,a as o,E as n,ag as d}from"./chunks/framework.DMVuHR7L.js";const w=JSON.parse('{"title":"Files","description":"","frontmatter":{},"headers":[],"relativePath":"features/files.md","filePath":"features/files.md","lastUpdated":1778597765000}'),h={name:"features/files.md"};function p(u,e,g,c,f,m){const i=r("ThemeImage");return s(),l("div",null,[e[0]||(e[0]=t("h1",{id:"files",tabindex:"-1"},[o("Files "),t("a",{class:"header-anchor",href:"#files","aria-label":'Permalink to "Files"'},"​")],-1)),e[1]||(e[1]=t("p",null,[o("The Files widget is a two-pane file browser over the "),t("strong",null,"ADB sync protocol"),o(" — the same protocol "),t("code",null,"adb push"),o(" and "),t("code",null,"adb pull"),o(" use under the hood. Browse the device, pull files out by drag-and-drop, push files in by dropping them onto the pane.")],-1)),n(i,{"src-dark":"/img/features/files-default.png","src-light":"/img/features/files-default-light.png",alt:"Files tile"}),e[2]||(e[2]=d('<h2 id="browsing" tabindex="-1">Browsing <a class="header-anchor" href="#browsing" aria-label="Permalink to &quot;Browsing&quot;">​</a></h2><ul><li>The <strong>left pane</strong> is a directory tree, expanding lazily as you click.</li><li>The <strong>right pane</strong> is the file listing for the focused directory, with type, size, and modification date.</li><li>The breadcrumb at the top shows the current path; click any segment to jump.</li></ul><p>The default starting path is <code>/sdcard/Download</code>. Override it in the cog modal.</p><h2 id="pulling-files-device-→-laptop" tabindex="-1">Pulling files (device → laptop) <a class="header-anchor" href="#pulling-files-device-→-laptop" aria-label="Permalink to &quot;Pulling files (device → laptop)&quot;">​</a></h2><p>Drag any file or directory from the right pane onto your operating system&#39;s file browser, the desktop, or a folder. The widget streams the file out via the sync protocol; for transfers ≥1 MB a progress bar appears in the lower-right.</p><p>You can also <strong>right-click → Pull to…</strong> to choose a destination explicitly.</p><h2 id="pushing-files-laptop-→-device" tabindex="-1">Pushing files (laptop → device) <a class="header-anchor" href="#pushing-files-laptop-→-device" aria-label="Permalink to &quot;Pushing files (laptop → device)&quot;">​</a></h2><p>Drop files (or directories) from the OS onto the right pane to push them into the focused directory. The widget queues them and streams them up, showing per-file progress. Existing files are overwritten only if you confirm.</p><h2 id="drag-onto-other-widgets" tabindex="-1">Drag onto other widgets <a class="header-anchor" href="#drag-onto-other-widgets" aria-label="Permalink to &quot;Drag onto other widgets&quot;">​</a></h2><p>Files rows are draggable onto two other widgets in the dashboard:</p><ul><li><strong>Shell.</strong> Drop a row onto a Shell prompt to paste the file&#39;s device-side path at the cursor — handy for piping a path into any command without retyping it. The file is <em>not</em> pulled to your laptop in this case.</li><li><strong>Screen Mirror.</strong> Drop a row onto the Mirror surface to open the file on the device (APK install or <code>am start VIEW</code>). See the <a href="./screen-mirror#open-files-on-device">Screen Mirror</a> page for the full handoff.</li></ul><p>In both cases the in-app drop suppresses the default Pull-to-laptop behaviour — only OS-level drops (desktop, Finder, Explorer) trigger the download.</p><h2 id="per-widget-settings" tabindex="-1">Per-widget settings <a class="header-anchor" href="#per-widget-settings" aria-label="Permalink to &quot;Per-widget settings&quot;">​</a></h2><ul><li><strong>Starting path.</strong> Where the widget mounts.</li><li><strong>Hidden files.</strong> Show / hide dot-files.</li><li><strong>Sort.</strong> Name, size, or modified time.</li></ul><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>WebUSB throughput tops out around 30–60 MB/s on USB 3 cables. Multi-GB pushes are workable but not as fast as a native <code>adb push</code>.</li><li>Android scoped-storage rules apply. App-private directories under <code>/data/data/&lt;pkg&gt;/</code> aren&#39;t readable on production builds without root.</li></ul>',16))])}const y=a(h,[["render",p]]);export{w as __pageData,y as default};
